  // "defender is right behind him": a red ring round the defender's chest and a short red arrow into his back
  const dr=easeOutBack(sm(C2.def,C2.def+.35,tt))*(1-sm(C2.keeps,C2.keeps+.3,tt));
  if(dr>.02){const c=jointPt(st,FA,df,'chest'),r=kAt(st,depth(FA,df))*.42*dr;s.fill(R,ribbon(blob(c[0],c[1],r,r*1.1,220,{n:22}),9,{seed:221,close:true,wobble:1}),1);}
